import{gerarProjetos}from"./projetos.js";import{carregarCadastros,configurarFormulario}from"./cadastro.js";const conteudo=document.querySelector("#conteudo"),links=document.querySelectorAll("nav a");links.forEach(function(o){o.addEventListener("click",async function(t){const e=o.getAttribute("href");if("projetos.html"===e){t.preventDefault();const o=await fetch(e),r=await o.text(),a=(new DOMParser).parseFromString(r,"text/html").querySelector("main");conteudo.innerHTML=a.innerHTML,gerarProjetos()}if("cadastro.html"===e){t.preventDefault();const o=await fetch(e),r=await o.text(),a=(new DOMParser).parseFromString(r,"text/html").querySelector("main");conteudo.innerHTML=a.innerHTML,carregarCadastros()}if("projetos.html#ajudar"===e){t.preventDefault();const o=await fetch("projetos.html"),e=await o.text(),r=(new DOMParser).parseFromString(e,"text/html").querySelector("main");conteudo.innerHTML=r.innerHTML,gerarProjetos(),document.querySelector("#ajudar").scrollIntoView()}})});const botaoModoEscuro=document.getElementById("modo-escuro");botaoModoEscuro&&botaoModoEscuro.addEventListener("click",()=>{document.body.classList.toggle("modo-escuro");const o=document.body.classList.contains("modo-escuro");botaoModoEscuro.textContent=o?"Modo claro":"Modo escuro",botaoModoEscuro.setAttribute("aria-pressed",o)});